#include <stdio.h>

/* 三步手艺已经写好了，别动 */
int fish_prep(int raw) {
    return raw + {p};
}

int fish_knead(int x) {
    return x * {k};
}

int fish_burn(int x) {
    return x - {l};
}

/* ===== 身子区：fish_bake 的身子 ===== */
int fish_bake(int raw) {
    int prepared = fish_prep(raw);
    int kneaded = fish_knead(prepared);
    return fish_burn(kneaded);
}

int main(void) {
    printf("成品 %d 条\n", fish_bake({raw}));
    return 0;
}
